/-- Matroid `M` that can be represented over any field -/
def Matroid.IsRegular [DecidableEq α] (M : Matroid α) : Prop :=
  ∀ F : Type, ∀ _F : Field F, M.IsRepresentableOver F

/-- The main way of creating a 2-sum of any matroids. -/
def TwoSumAssumptions.build2sum {M₁ M₂ : Matroid α} (assumptions : TwoSumAssumptions M₁ M₂) : Matroid α :=
  assumptions.build2sumCircuitMatroid.toMatroid

/-- Matroid `M` is binary if it is representable over `Z2` -/
def Matroid.IsBinary [DecidableEq α] (M : Matroid α) : Prop :=
  M.IsRepresentableOver Z2
